import{_ as a,o as e,c as s,aw as o}from"./chunks/framework.DLufY-ao.js";const h=JSON.parse('{"title":"DOM","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-web-api/dom/dom.md","filePath":"wiki/dev-commit/js/js-web-api/dom/dom.md"}'),i={name:"wiki/dev-commit/js/js-web-api/dom/dom.md"};function n(t,l,r,p,c,d){return e(),s("div",null,[...l[0]||(l[0]=[o(`<h1 id="dom" tabindex="-1">DOM <a class="header-anchor" href="#dom" aria-label="Permalink to &quot;DOM&quot;">​</a></h1><ul><li>**Document Object Model (DOM) ** - объектная модель представления документа. Независящий от платформы и языка программирования способ представления документа, позволяющий программам и скриптам получить доступ к содержимому HTML, XHTML и XML документов, а также изменять содержимое, структуру и оформление таких документов</li><li>DOM - это представление документа в виде дерева объектов, доступное для изменения через JavaScript</li><li>Всё содержимое документа представлено в виде иерархии объектов</li><li>Структура этой иерархии стандартизирована, чтобы обеспечить независимость от платформы</li></ul><h2 id="автоисправление" tabindex="-1">Автоисправление <a class="header-anchor" href="#автоисправление" aria-label="Permalink to &quot;Автоисправление&quot;">​</a></h2><ul><li>Всегда будет верхний тег html и body. Даже если в тексте нет – в DOM он будет, браузер создаст его самостоятельно</li><li>Браузер закрывает теги и т.д.</li><li>Таблицы всегда содержат tbody, браузер добавляет самостоятельно</li></ul><h2 id="chrome-dev-tools-elements" tabindex="-1">Chrome Dev Tools (Elements) <a class="header-anchor" href="#chrome-dev-tools-elements" aria-label="Permalink to &quot;Chrome Dev Tools (Elements)&quot;">​</a></h2><ul><li>Computed Style - итоговые свойства CSS элемента, которые он приобрёл в результате применения всего каскада стилей, включая внешние CSS-файлы и атрибут style</li><li>Style - каскад стилей, применённый к элементу. Каждое стилевое правило отдельно, здесь же можно менять стили кликом</li></ul><h3 id="методы-консоли" tabindex="-1">Методы консоли <a class="header-anchor" href="#методы-консоли" aria-label="Permalink to &quot;Методы консоли&quot;">​</a></h3><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#383A42;">$0           </span><span style="color:#A0A1A7;font-style:italic;">// последний элемент, выбранный во вкладке Elements</span></span>
<span class="line"><span style="color:#383A42;">$1           </span><span style="color:#A0A1A7;font-style:italic;">// предыдущий элемент, выбранный во вкладке Elements</span></span>
<span class="line"><span style="color:#4078F2;">$$</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;div.my&quot;</span><span style="color:#383A42;">) </span><span style="color:#A0A1A7;font-style:italic;">// ищет все элементы в DOM по данному CSS-селектору.</span></span>
<span class="line"><span style="color:#4078F2;">$</span><span style="color:#383A42;">(</span><span style="color:#50A14F;">&quot;div.my&quot;</span><span style="color:#383A42;">)  </span><span style="color:#A0A1A7;font-style:italic;">// ищет первый элемент в DOM по данному CSS-селектору.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#383A42;">$0.</span><span style="color:#E45649;">style</span><span style="color:#383A42;">.</span><span style="color:#E45649;">backgroundColor</span><span style="color:#0184BC;"> =</span><span style="color:#50A14F;"> &#39;red&#39;</span><span style="color:#383A42;">;</span></span></code></pre></div><h2 id="особенности" tabindex="-1">Особенности <a class="header-anchor" href="#особенности" aria-label="Permalink to &quot;Особенности&quot;">​</a></h2><ul><li>Если скрипт находится в head, в нём недоступен document.body, который еще не существует</li><li>В DOM в качестве значения, обозначающего «нет такого элемента» или «узел не найден», используется не undefined, а null</li><li>Все навигационные свойства - только для чтения. Нельзя заменить элемент присвоением childNodes[i] = ...</li></ul><h3 id="коллекции-–-не-массивы" tabindex="-1">Коллекции – не массивы <a class="header-anchor" href="#коллекции-–-не-массивы" aria-label="Permalink to &quot;Коллекции – не массивы&quot;">​</a></h3><ul><li><p>DOM-коллекции, такие как childNodes, не являются массивами. В них нет методов массивов, таких как forEach, map, push, pop и других. Их называют «коллекция» или «псевдомассив»</p></li><li><p>Для перебора коллекции используется цикл for(let i=0; i&lt;elems.length; i++) ...</p></li><li><ol><li>Применить метод массива через call/apply</li></ol></li><li><ol start="2"><li>При помощи Array.prototype.slice сделать из коллекции массив</li></ol></li><li><p>Обычно вызов arr.slice(a, b) делает новый массив и копирует туда элементы arr с индексами от a до b-1 включительно. Если же вызвать его без аргументов arr.slice(), то он делает новый массив и копирует туда все элементы arr</p></li><li><p>Нельзя перебирать коллекцию через for..in</p></li><li><p>Колеекции похожи на массивы, но у них есть свои свойства и методы, которых в массивах нет</p></li><li><p>Цикл for..in выведет не только индексы 0, 1, 2, по которым лежат узлы в коллекции, но и свойство length (в коллекции оно enumerable), а также функцию item(n) – она никогда не используется, возвращает n-й элемент коллекции, проще обратиться по индексу [n]</p></li></ul><hr><ul><li>console.log - выводит элемент в виде, удобном для исследования HTML-структуры</li><li>console.dir - выводит элемент в виде JavaScript-объекта, удобно для анализа его свойств</li></ul>`,14)])])}const u=a(i,[["render",n]]);export{h as __pageData,u as default};
